import { randomUUID } from 'node:crypto';
import { cp, mkdir, mkdtemp, readdir, lstat, stat, readFile, realpath, rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createRequire } from 'node:module';
import { z } from 'zod';
import { resolveSkillSource, snapshotSkillFolder } from './carb-skill-source.js';
import { registerInstalledSkill, removeInstalledSkill } from './carb-skill-ownership.js';
import { globalSkillsRoot } from './carb-global-skills.js';

const yaml = createRequire(import.meta.url)('js-yaml');

const previews = new Map(), globalLocks = new Set();
const localSourceTypes = new Set(['zip', 'folder']);
const expiry = 20 * 60 * 1000;
const baseParams = { provider: z.string().min(1).max(80), projectPath: z.string().min(1).max(4096).optional() };
export const skillInstallMethods = {
  'skills.previewInstall': { params: z.object({ ...baseParams, source: z.string().trim().min(1).max(4096) }), result: z.unknown() },
  'skills.commitInstall': { params: z.object({ ...baseParams, previewId: z.string().uuid(), skillIds: z.array(z.string().uuid()).min(1).max(100) }), result: z.unknown() },
  'skills.discardInstall': { params: z.object({ previewId: z.string().uuid() }), result: z.object({}) },
};
const timer = setInterval(() => { for (const [id, item] of previews) if (!item.busy && item.expiresAt < Date.now()) { previews.delete(id); void item.cleanup().catch(() => {}); } }, 60000);
timer.unref();

async function exists(filename) { return lstat(filename).then(() => true, error => { if (error.code === 'ENOENT') return false; throw error; }); }
async function projectFolder(projectPath) {
  const project = await realpath(projectPath).catch(() => { throw new Error('项目文件夹不存在，请重新选择项目。'); });
  if (!(await stat(project)).isDirectory()) throw new Error('安装目标需要是项目文件夹。');
  return project;
}

async function globalFolder() {
  const root = path.resolve(globalSkillsRoot());
  await mkdir(root, { recursive: true });
  const info = await lstat(root);
  if (!info.isDirectory() || info.isSymbolicLink()) throw new Error('全局技能目录必须是普通文件夹。');
  return root;
}

async function installGlobalSkill(folderPath) {
  const source = await realpath(folderPath);
  const name = path.basename(source);
  const root = await globalFolder();
  const destination = path.join(root, name);
  if (await exists(destination)) throw new Error(`全局技能「${name}」已存在，未覆盖现有文件。`);
  await mkdir(destination);
  await registerInstalledSkill(destination);
  try {
    for (const entry of await readdir(source)) await cp(path.join(source, entry), path.join(destination, entry), { recursive: true, dereference: true, errorOnExist: true, force: false });
    return destination;
  } catch (error) { await removeInstalledSkill(destination).catch(() => {}); throw error; }
}

async function skillMetadata(folderPath) {
  const filename = path.join(folderPath, 'SKILL.md'), info = await lstat(filename);
  if (!info.isFile() || info.size > 1024 * 1024) throw new Error('SKILL.md 必须是小于 1 MB 的普通文件。');
  const markdown = (await readFile(filename, 'utf8')).replace(/^\uFEFF/, '');
  const match = /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/.exec(markdown);
  if (!match) throw new Error('SKILL.md 缺少 YAML 元数据，请填写 name 和 description。');
  let metadata;
  try { metadata = yaml.load(match[1], { schema: yaml.JSON_SCHEMA }); } catch { throw new Error('SKILL.md 的 YAML 元数据格式无效。'); }
  const name = typeof metadata?.name === 'string' ? metadata.name.trim() : '';
  const description = typeof metadata?.description === 'string' ? metadata.description.trim() : '';
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(name) || name.length > 64 || /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])$/i.test(name)) throw new Error('技能 name 需要为不超过 64 字符的小写字母、数字和单连字符。');
  if (!description || description.length > 4096) throw new Error('技能 description 不能为空或超过 4096 字符。');
  return { name, description };
}

async function discoverSkills(root) {
  const found = [], warnings = []; let visited = 0;
  async function visit(folder, depth) {
    if (++visited > 2000 || depth > 16) throw new Error('技能包目录过多或层级过深。');
    if (await exists(path.join(folder, 'SKILL.md'))) {
      const relativePath = path.relative(root, folder).split(path.sep).join('/') || '.';
      try { found.push({ folderPath: folder, relativePath, ...await skillMetadata(folder) }); }
      catch (error) { warnings.push(`${relativePath}: ${error.message}`); }
      return;
    }
    for (const entry of await readdir(folder, { withFileTypes: true })) if (entry.isDirectory() && !entry.name.startsWith('.') && entry.name !== 'node_modules' && entry.name !== '__MACOSX') await visit(path.join(folder, entry.name), depth + 1);
  }
  await visit(root, 0);
  if (!found.length) throw new Error(warnings.length ? warnings.join('\n') : '未找到有效技能。本地 ZIP 或技能文件夹内需要包含带 name 和 description 的 SKILL.md。');
  if (found.length > 100) throw new Error('单次最多导入 100 个技能，请选择具体的技能子目录。');
  return { found, warnings };
}

export async function previewSkillInstall(orchestrator, params) {
  if (previews.size >= 10) throw new Error('待安装的预览过多，请关闭其他预览后重试。');
  const source = await resolveSkillSource(params.source);
  let snapshot;
  try {
    if (!localSourceTypes.has(source.sourceType)) throw new Error('仅支持本地 ZIP 文件或技能文件夹，请重新选择本地来源。');
    const { found, warnings } = await discoverSkills(source.folderPath);
    snapshot = await mkdtemp(path.join(os.tmpdir(), 'carb-skill-preview-'));
    const skills = [], names = new Map();
    for (const skill of found) names.set(skill.name, (names.get(skill.name) ?? 0) + 1);
    for (const [index, skill] of found.entries()) {
      const folderPath = path.join(snapshot, String(index), skill.name);
      const totals = await snapshotSkillFolder(skill.folderPath, folderPath);
      const destination = path.join(await globalFolder(), skill.name);
      const alreadyExists = await exists(destination);
      const blockedReason = names.get(skill.name) > 1 ? '包内包含同名技能，请分别导入。' : alreadyExists ? '全局技能目录已存在同名技能，现有文件会保留。' : undefined;
      skills.push({ id: randomUUID(), name: skill.name, description: skill.description, relativePath: skill.relativePath, ...totals, alreadyExists, ...(blockedReason ? { blockedReason } : {}), folderPath });
    }
    const previewId = randomUUID(), expiresAt = Date.now() + expiry;
    previews.set(previewId, { provider: params.provider, sourceType: source.sourceType, skills, expiresAt, busy: false, cleanup: () => rm(snapshot, { recursive: true, force: true }) });
    return { previewId, sourceType: source.sourceType, sourceLabel: source.sourceLabel, destination: await globalFolder(), expiresAt, warnings, skills: skills.map(({ folderPath, ...publicSkill }) => publicSkill) };
  } catch (error) { if (snapshot) await rm(snapshot, { recursive: true, force: true }); throw error; }
  finally { await source.cleanup(); }
}

export async function discardSkillInstall({ previewId }) {
  const item = previews.get(previewId);
  if (!item) return {};
  if (item.busy) throw new Error('安装正在进行，请等待安装完成。');
  previews.delete(previewId); await item.cleanup(); return {};
}

export async function commitSkillInstall(orchestrator, params) {
  const item = previews.get(params.previewId);
  if (!item || item.expiresAt < Date.now()) throw new Error('技能预览已过期，请重新检查来源后安装。');
  if (!localSourceTypes.has(item.sourceType)) throw new Error('此预览不是本地安装来源，请重新选择本地 ZIP 文件或技能文件夹。');
  if (item.provider !== params.provider) throw new Error('代理已更改，请重新预览后安装。');
  // Repeating a request after a lost WebSocket reply returns the same receipt.
  if (item.result) return item.result;
  if (item.busy || globalLocks.has(globalSkillsRoot())) throw new Error('全局技能安装正在进行中，请稍后重试。');
  const selected = [...new Set(params.skillIds)].map(id => item.skills.find(skill => skill.id === id));
  if (selected.some(skill => !skill)) throw new Error('技能选择无效，请重新预览。');
  if (selected.some(skill => skill.blockedReason)) throw new Error('所选技能存在名称冲突，请取消选择冲突项。');
  item.busy = true; globalLocks.add(globalSkillsRoot());
  const installed = [];
  try {
    for (const skill of selected) if (await exists(path.join(await globalFolder(), skill.name))) throw new Error(`全局技能「${skill.name}」已存在，未覆盖现有文件。`);
    for (const skill of selected) { const destination = await installGlobalSkill(skill.folderPath); installed.push({ id: destination, name: skill.name, description: skill.description, source: { type: 'folder', path: destination }, dependencyErrors: [] }); }
    const warnings = installed.flatMap(skill => (skill.dependencyErrors ?? []).map(error => `${skill.name}: ${error.message}`));
    item.result = { installed, warnings }; item.expiresAt = Date.now() + expiry;
    await item.cleanup().catch(() => item.result.warnings.push('安装已完成，临时预览文件将在稍后清理。'));
    return item.result;
  } catch (error) {
    const failedRollback = [];
    for (let index = installed.length - 1; index >= 0; index--) {
      const name = selected[index].name;
      const expected = path.join(await globalFolder(), name);
      await removeInstalledSkill(expected).catch(() => failedRollback.push(name));
    }
    if (failedRollback.length) throw new Error(`${error.message}；部分目录无法回滚：${failedRollback.join('、')}，请检查项目技能列表。`);
    if (!installed.length) throw error;
    throw new Error(`${error.message}；本次已安装项已回滚，可重试。`);
  } finally { item.busy = false; globalLocks.delete(globalSkillsRoot()); }
}

// Used by the legacy direct-install endpoint; ZIPs and folders containing
// several skills require the explicit preview/selection flow.
export async function resolveSingleSkillSource(input) {
  const source = await resolveSkillSource(input);
  let normalized;
  try {
    const { found } = await discoverSkills(source.folderPath);
    if (found.length !== 1) throw new Error('来源包含多个技能，请在安装页面预览并选择要安装的技能。');
    const skill = found[0];
    if (path.basename(skill.folderPath) === skill.name) return { ...source, folderPath: skill.folderPath };
    normalized = await mkdtemp(path.join(os.tmpdir(), 'carb-skill-single-'));
    const folderPath = path.join(normalized, skill.name); await snapshotSkillFolder(skill.folderPath, folderPath);
    return { ...source, folderPath, cleanup: async () => { await source.cleanup(); await rm(normalized, { recursive: true, force: true }); } };
  } catch (error) { await source.cleanup(); if (normalized) await rm(normalized, { recursive: true, force: true }); throw error; }
}

// Keep the legacy single-skill endpoint aligned with the global preview flow.
// Multi-skill archives must use previewInstall so the user can select entries.
export async function installSingleGlobalSkill(input) {
  const source = await resolveSingleSkillSource(input);
  try {
    const metadata = await skillMetadata(source.folderPath);
    const destination = await installGlobalSkill(source.folderPath);
    return { id: destination, ...metadata, source: { type: 'folder', path: destination }, dependencyErrors: [] };
  } finally { await source.cleanup(); }
}
